#!/usr/bin/env python3
import json

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    output = [[0] * cols for _ in range(rows)]

    for col in range(cols):
        objs = []
        for r in range(rows):
            if grid[r][col] != 0:
                objs.append((r, grid[r][col]))

        if not objs:
            continue

        # Sort by row descending
        objs_sorted = sorted(objs, key=lambda x: x[0], reverse=True)
        k = len(objs_sorted)

        for p, (in_r, val) in enumerate(objs_sorted):
            if k == 1:
                if in_r >= 7:
                    out_r = 6
                elif in_r >= 4:
                    out_r = 7
                else:
                    out_r = 8
            else:
                out_r = 6 + p

            if 0 <= out_r < rows:
                output[out_r][col] = val

    return output
